//! Entry point of the WP-6.2 fixture app (same shape as the template's
//! `src/main.rs`): the TSX project's modules are generated by
//! `zant_build::tsx_app()` into `$OUT_DIR/main.rs` and included at the crate
//! root (`#[path]` inside it resolves relative to `$OUT_DIR`).
//!
//! `cargo build` on this fixture is what `scripts/tsx/build-check.sh` runs to
//! prove the build-script helper end to end.

#![allow(clippy::redundant_clone)]

// The generated modules call `nodes!` unqualified; `zant-tsx`'s module
// preamble does not import it yet (WP-5.4 integration gap, reported by
// WP-6.2), so the app imports the macro crate-wide until the preamble does.
#[macro_use]
extern crate zant;

mod app_config;

// Native modules live next to `src/` (the fixture keeps one empty module so the
// layout matches the template).
#[path = "../native/lib.rs"]
mod native;

include!(concat!(env!("OUT_DIR"), "/main.rs"));

fn main() -> zant::Result<()> {
    native::register();
    zant::tsx::app::run::<crate::app::App>(zant::tsx::app::Config {
        title: app_config::title.to_string(),
        window: app_config::window,
        bundle_id: app_config::bundle_id.to_string(),
        single_instance: app_config::single_instance,
        watch_clipboard: false,
    })
}
